import { FC, HTMLAttributes } from 'react';

import { Flex, Typography } from 'antd';
import cn from 'classnames';

import { PlannerDayPost, PlannerPost, usePlannerDates } from 'features/Planner';
import { formatDate } from 'shared/utils';

import { PlannerPosts } from '../PlannerPosts/PlannerPosts';

import styles from './PlannerDayLine.module.scss';

interface IPlannerDayLineProps extends HTMLAttributes<HTMLDivElement> {
	posts: PlannerPost[];
	time: string;
}

export const PlannerDayLine: FC<IPlannerDayLineProps> = ({ className, time, posts, ...props }) => {
	const { selectedDate } = usePlannerDates();

	const isNow =
		time === formatDate(new Date(), 'shortTime') &&
		selectedDate.toLocaleDateString() === new Date().toLocaleDateString();

	return (
		<Flex {...props} gap={4} justify="space-between" className={cn(styles.plannerDayLine, className)}>
			<Flex vertical gap={4} className={styles.left}>
				<Typography.Text
					type={!posts.length ? 'secondary' : undefined}
					className={cn(styles.time, { [styles.now]: isNow })}>
					{time}
				</Typography.Text>
				{!!posts.length && <PlannerPosts posts={posts} vertical isDay />}
			</Flex>

			<Flex align="center" justify="center" className={styles.separator}>
				<div className={styles.line}></div>
				<div className={cn(styles.dot, { [styles.now]: isNow })}></div>
			</Flex>

			<Flex vertical align="start" gap={8} className={styles.content}>
				{!!posts.length && posts.map((post) => <PlannerDayPost key={post.id} post={post} />)}
				{!posts.length && <div className={cn(styles.empty, { [styles.now]: isNow })}></div>}
			</Flex>
		</Flex>
	);
};
